let locale = DEFAULT_LOCALE;
export function getLocale() { return locale; }
export function setLocale(next) { locale = catalogs[next] ? next : DEFAULT_LOCALE; return locale; }
export function detectLocale(languages = []) {
 for (const language of languages) { if (/^zh/i.test(language)) return 'zh-CN'; if (/^en/i.test(language)) return 'en'; }
 return 'en';
}
export function t(key, params) {
 const text = catalogs[locale][key] ?? catalogs.en[key] ?? key;
 return params ? text.replace(/\{(\w+)\}/g, (match, name) => name in params ? String(params[name]) : match) : text;
}
export function messageKeys(id) { return Object.keys(catalogs[id] || {}); }
